import{_ as t,o as a,c as s,aa as i}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/media/en/tickets/en_dashboard.png",o="/buildary-help-preview/media/en/tickets/en_dashboard_rozcestnik.png",n="/buildary-help-preview/media/en/tickets/en_kalendar.png",d="/buildary-help-preview/media/en/tickets/en_dashboard_grafy.png",h="/buildary-help-preview/media/en/tickets/en_dashboard_seznamy.png",w=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{"title":"Dashboard","wiki":"en:tickets:dashboard"},"headers":[],"relativePath":"en/tickets/dashboard.md","filePath":"en/tickets/dashboard.md","lastUpdated":1794388980000}'),l={name:"en/tickets/dashboard.md"};function c(p,e,g,u,k,b){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><figure class="shot" style="--w:620px;"><img src="'+r+'" alt="Dashboard - Task Overview" width="600" loading="lazy"></figure><p>The Dashboard is an <strong>interactive task overview</strong>, serving both as a simple overview of tasks according to their individual phases and as a quick navigation hub.</p><p>Functionally and visually, it consists of three parts:</p><ol><li>the top row with the current date and navigation options</li><li>task overview charts according to three different criteria</li><li>two task lists organized by deadline</li></ol><p>Each part is described in more detail below.</p><h2 id="_1-top-row-date-navigation-calendar" tabindex="-1">1/ Top Row - Date, Navigation, Calendar <a class="header-anchor" href="#_1-top-row-date-navigation-calendar" aria-label="Permalink to &quot;1/ Top Row - Date, Navigation, Calendar&quot;">​</a></h2><img src="'+o+'" alt="Top Bar - Dashboard" width="500" loading="lazy"> The top row of the Dashboard window displays the current date and 4 buttons: - **Ticket List** → the button displays the number of completed / in-progress / not-started tickets and opens the Ticket List page - **Drawings** → the number indicates the number of tickets localized on drawings and opens the Drawings and Map page on the Drawings tab - **Map** → the number indicates the number of tickets localized on the map and opens the Drawings and Map page on the Map tab - **Open Calendar** → <figure class="shot" style="--w:300px;"><img src="'+n+'" alt="Calendar" width="300" loading="lazy"></figure><p>opens the calendar in the right part of the Dashboard window, showing the current month with enabled, color-coded filters for tickets that are starting / ending / in progress.</p><p>These filters can be turned on or off above the displayed month according to the required view.</p><p>Selecting a day in the calendar displays a list of that day&#39;s tickets below the calendar.</p><p>Clicking the name of a specific ticket opens the ticket for editing.</p><h2 id="_2-charts" tabindex="-1">2/ Charts <a class="header-anchor" href="#_2-charts" aria-label="Permalink to &quot;2/ Charts&quot;">​</a></h2><img src="'+d+'" alt="Charts" width="600" loading="lazy"> The doughnut charts provide an overview of the number of tickets according to different criteria. Users can see up to 3 charts: - The **My Tickets** chart ⇒ contains a summary of tickets for which the user is an **assignee or approver**. - The **All Tickets** chart ⇒ is available only to users **with permission to view all tickets**. <p>The tickets shown in these two charts are grouped <strong><strong>by ticket status</strong></strong> (excluding the &quot;Draft&quot; status, as tickets of this type represent a non-editable template and are therefore not included in the chart).</p><ul><li>The <strong>Categories</strong> chart ⇒ groups the same tickets as the chart to its left, but <strong><strong>by ticket category</strong></strong>. In other words, a &quot;regular&quot; user sees their &quot;My Tickets&quot; in this chart, while a user with higher permissions gets an overview of all tickets grouped by category.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>The charts are interactive</strong>. Clicking on a colored section of the chart representing a particular ticket type takes the user to the Ticket List page with tickets filtered according to the selected parameters. The list therefore shows exactly the tickets represented by the selected section of the chart.</p></div><h2 id="_3-task-lists-by-deadline" tabindex="-1">3/ Task Lists by Deadline <a class="header-anchor" href="#_3-task-lists-by-deadline" aria-label="Permalink to &quot;3/ Task Lists by Deadline&quot;">​</a></h2><figure class="shot" style="--w:620px;"><img src="'+h+'" alt="Lists by Deadline" width="600" loading="lazy"></figure><p>The third part of the Dashboard consists of two task lists organized by deadline:</p><ul><li><strong>Due This Week</strong> ⇒ includes unfinished tickets whose scheduled end date falls within the upcoming days of the current calendar week. Depending on the user&#39;s permissions, the list displays either tickets for which the user is the assignee or approver, or all tickets.<br>The <strong>All Tickets Due This Week</strong> button opens the Ticket List page with a filter showing tickets for the current week from Monday to Sunday, regardless of ticket status.</li><li><strong>Overdue Tickets</strong> ⇒ includes unfinished tickets whose deadline has passed, again showing either tickets for which the user is the assignee or approver, or all tickets.<br>The <strong>All Overdue Tickets</strong> button opens the Ticket List page with a filter showing unfinished overdue tickets.</li></ul><p>Clicking the name of a ticket opens its details.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Tickets that were due on previous days of the current week but were not completed are automatically moved to the overdue ticket list once their missed deadline has passed.</p></div>',26)])])}const m=t(l,[["render",c]]);export{w as __pageData,m as default};
